SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'einzugsflaechen_not', 'Einzugsflächen der Notentwässerung (Teilfläche, A, C → Σ A, Σ A·C)', 'json', NULL, false, 'Anhang 1 (informativ), Gl. 1; §4.8', 'Plan 3: Zeilen je Teilfläche (Beispiel L6477–L6485: 800 m2, C = 1); Σ → sum_a_m2 (FLL-GAR-27-D1) / sum_ac (FLL-GAR-27-D2); die prod-Gleichung Gl. 1 Q_NOT liest die Skalare A / C weiter (Umstellung auf die Summen STAGED fll_gar-R-1); r5,100 / r5,5 nach DIN 1986-100 bleiben Eingaben (Content-Boundary — L5716); das Duplikat A_einzugsflaeche ist fll_gar-X-1 (FLL-Revision GAR-27 F1).', 'imported_unverified', 'zu aufgehenden Gebäudeteilen ist ein Notüberlauf vorzusehen. Dieser ist mit einem kanal-  
unabhängigem Entwässerungskonzept nach DIN 1986-100 mit örtlicher 100-Jahres-Regen-  
spende r5,100 zu dimensionieren. — 12 Beispielsberechnung für einen Notüberlauf für einen 800 m2 großen Teich in Düsseldorf  
13 nach DIN 1986-100:  
14 Für Düsseldorf gilt: r5,5 \= 316 l / (s\*ha) und r5,100 \= 607 l / (s\*ha),  
15 Abflusswirksame Fläche \= 800 m2  
16 Abflussbeiwert C \= 1  
17  
18 Berechnung:  
19 Q NOT \= \[ (r5,100 – (r5,5 \* C) \] \* (A / 10.000)  
20 \= ( (607 – 316 l/(s\*ha)) ) \* (800 m2 / 10.000) \= 23,28 l/sec  ', 'register', '{"title":"Einzugsflächen der Notentwässerung (Anhang 1)","subtitle":"Anhang 1 Gl. 1 — je Teilfläche abflusswirksame Fläche A und Abflussbeiwert C; Σ A und Σ A·C für Q_NOT = (r5,100 − r5,5·C)·A/10.000","add_label":"+ Teilfläche","placement":"section","columns":[{"key":"label","label":"Teilfläche","type":"text","required":true},{"key":"a_m2","label":"Abflusswirksame Fläche A","type":"number","unit":"m²","required":true,"min":0,"aria_label":"abflusswirksame Fläche der Teilfläche"},{"key":"c","label":"Abflussbeiwert C","type":"number","required":true,"min":0,"max":1,"aria_label":"Abflussbeiwert der Teilfläche"},{"key":"ac","label":"A · C","type":"derived","expr":"a_m2 * c"}],"footer":["sum_a_m2","sum_ac"],"note":"1 Anhang (informativ) 2 Anhang 1 3 Beispielsberechnung für eine Überschusswasserableitung 4 Die Dimensionierung des Regelüberlaufs von Gewässern erfolgt unter Zugrundelegung eines 5 standortbezogenen fünfminütigen Regenereignisses, das statistisch alle fünf Jahre auftreten 6 kann (r5,5)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
